        saveTitle(sqBubbleData.call(this, titleCount, bookId, chapterId, titlePid, !!(titleItem.isHotParagraph || titleItem.IsHotParagraph), "chapter", titleText));
    } else {
        saveTitle("");
    }
    if (!cfg.paragraph) return content;

    var pieces = String(content || "").split(/(<br\s*\/?>)/i);
    var textIndexes = [];
    for (var i = 0; i < pieces.length; i++) {
        if (!/^<br\s*\/?>$/i.test(pieces[i]) && String(pieces[i]).trim()) textIndexes.push(i);
    }
    for (var b = 0; b < bodyItems.length; b++) {
        var bodyItem = bodyItems[b] || {};
        var bodyOrder = Number(bodyItem.orderId !== undefined ? bodyItem.orderId : bodyItem.OrderId);
        var bodyCount = Number(bodyItem.commentCount || bodyItem.CommentCount || 0);
        var bodyPid = bodyItem.paragraphId || bodyItem.ParagraphId || ("p" + String(bodyOrder));
        var target = textIndexes[bodyOrder - 1];
        if (target !== undefined) {
            var bodyText = String(bodyItem.text || bodyItem.Text || bodyItem.summaryText || bodyItem.SummaryText || pieces[target] || "");
            pieces[target] += sqBubbleImage.call(this, bodyCount, bookId, chapterId, bodyPid, !!(bodyItem.isHotParagraph || bodyItem.IsHotParagraph), bodyText);
        }
    }
    return pieces.join("");
}

function sqEscapeHtml(value) {
    return String(value == null ? "" : value)
        .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

function sqRichText(comment) {
    var raw = String(comment && (comment.richText || comment.text) || "");
    var images = [];
    raw = raw.replace(/<img\b[^>]*>/gi, function(tag) {
        var match = tag.match(/src=["'](data:image\/(?:webp|png|gif);base64,[A-Za-z0-9+/=]+)["']/i);
        if (!match) return "";
        var token = "__SQ_EMOJI_" + images.length + "__";
        images.push('<img class="emoji" src="' + match[1] + '" alt="">');
        return token;
    });
    raw = sqEscapeHtml(raw).replace(/\r?\n/g, "<br>");
    for (var i = 0; i < images.length; i++) raw = raw.replace("__SQ_EMOJI_" + i + "__", images[i]);
    return raw;
}

function sqFormatTime(value) {
    var time = Number(value || 0);
    if (!time) return "";
    try { return sqJava.call(this).timeFormatUTC(time, "yyyy-MM-dd HH:mm", 28800000); } catch(e) { return ""; }
}

function sqReplyHtml(reply) {
    var name = sqEscapeHtml(reply && reply.nickname || "书友");
    var target = reply && reply.repliedUserNickname ? " 回复 " + sqEscapeHtml(reply.repliedUserNickname) : "";
    return '<div class="reply"><b>' + name + '</b>' + target + '：' + sqRichText(reply) + '</div>';
}

var _sqReplyDomSeq = 0;
function sqCommentCard(comment) {
    comment = comment || {};
    var avatar = String(comment.userPhoto || "");
    var replyData = comment.replies || {};
    var replies = sqList(replyData.commentList);
    var replyHtml = "";
    for (var i = 0; i < replies.length; i++) replyHtml += sqReplyHtml(replies[i]);
    var badges = comment.isAuthor ? '<span class="badge">作者</span>' : "";
    if (comment.fanCard && comment.fanCard.levelName) badges += '<span class="badge muted">' + sqEscapeHtml(comment.fanCard.levelName) + '</span>';

    var replyNum = Number(comment.replyNum || 0);
    var nextIndex = replyData.nextItemIndex;
    var hasMore = replyNum > replies.length && nextIndex !== null && nextIndex !== undefined && String(nextIndex) !== "";
    var safeMid = String(comment.mid || "comment").replace(/[^A-Za-z0-9_-]/g, "_");
    var replyTarget = "sq_replies_" + safeMid + "_" + (_sqReplyDomSeq++);
    var moreButton = hasMore
        ? '<button class="reply-more" type="button" data-target="' + replyTarget + '" data-mid="' + sqEscapeHtml(comment.mid || "") + '" data-cursor="' + sqEscapeHtml(nextIndex) + '" data-author="' + sqEscapeHtml(comment.authorId || "0") + '" onclick="sqLoadReplies(this)">展开更多回复</button>'
        : "";

    return '<article class="comment">' +
        '<div class="author">' + (avatar ? '<img class="avatar" src="' + sqEscapeHtml(avatar) + '">' : '<span class="avatar fallback"></span>') +
        '<div class="identity"><div><b>' + sqEscapeHtml(comment.nickname || "书友") + '</b>' + badges + '</div><time>' + sqFormatTime.call(this, comment.pubTime) + '</time></div>' +
        '<span class="likes">赞 ' + Number(comment.likes || 0) + '</span></div>' +
        '<div class="text">' + sqRichText(comment) + '</div>' +
        ((replyHtml || moreButton) ? '<div class="replies"><div id="' + replyTarget + '">' + replyHtml + '</div>' + moreButton + '</div>' : '') +
        '</article>';
}

function sqCards(list) {
    list = sqList(list);
    if (!list.length) return '<div class="empty">暂无评论</div>';
    var html = "";
    for (var i = 0; i < list.length; i++) html += sqCommentCard.call(this, list[i]);
    return html;
}

function sqBrowserConfig() {
    var cfg = sqCommentConfig.call(this);
    var height = Number(cfg.height || 80);
    if (height > 1) height = height / 100;
    if (!(height > 0 && height <= 1)) height = 0.8;
    return {
        state: 4,
        isHideable: true,
        heightPercentage: height,
        expandedCornersRadius: 16,
        dismissOnTouchOutside: true,
        widthPercentage: 1.0,
        maxWidth: -1,
        skipCollapsed: true,
